/* ════════════════════════════════════════════════════════════════
   NEON BREACH // interface system
   ════════════════════════════════════════════════════════════════ */
:root {
  --cyan: #6ff8ff;
  --cyan-dim: rgba(111, 248, 255, 0.52);
  --cyan-faint: rgba(111, 248, 255, 0.14);
  --pink: #ff2d87;
  --pink-bright: #ff72ad;
  --amber: #ffc15c;
  --green: #65ffb1;
  --danger: #ff4d5e;
  --ink: #04060d;
  --white: #f3fbff;
  --muted: rgba(208, 232, 245, 0.55);
  --panel: rgba(4, 10, 19, 0.72);
  --line: rgba(132, 220, 236, 0.18);
  --pad-x: clamp(18px, 3.4vw, 58px);
  --pad-y: clamp(14px, 2.4vh, 30px);
  --font-display: "Oxanium", "Arial Black", sans-serif;
  --font-body: "Chakra Petch", "Trebuchet MS", sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--white);
  font-family: var(--font-body);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}

body {
  user-select: none;
  touch-action: none;
  overscroll-behavior: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 45%, #0b1625 0%, #04060d 52%, #020309 100%);
}

#game-canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
}

.is-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
}

/* ── screen texture ───────────────────────────────────────────── */
.screen-fx {
  position: absolute;
  inset: 0;
  z-index: 8;
  pointer-events: none;
  overflow: hidden;
}

.scanlines {
  position: absolute;
  inset: 0;
  opacity: 0.22;
  background: repeating-linear-gradient(
    0deg,
    rgba(255, 255, 255, 0.045) 0px,
    rgba(255, 255, 255, 0.045) 1px,
    transparent 1px,
    transparent 3px
  );
  mix-blend-mode: soft-light;
}

.screen-vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center, transparent 45%, rgba(1, 3, 9, 0.45) 78%, rgba(1, 2, 7, 0.92) 100%),
    linear-gradient(180deg, rgba(0, 5, 14, 0.25), transparent 18%, transparent 82%, rgba(0, 3, 10, 0.35));
}

.chromatic-edge {
  position: absolute;
  inset: 0;
  box-shadow:
    inset 0 0 90px rgba(45, 184, 255, 0.07),
    inset 0 0 22px rgba(255, 45, 135, 0.05);
}

.damage-vignette {
  position: absolute;
  inset: 0;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 28%, rgba(255, 12, 47, 0.18) 64%, rgba(255, 8, 40, 0.76) 100%),
    linear-gradient(90deg, rgba(255, 20, 45, 0.25), transparent 18%, transparent 82%, rgba(255, 20, 45, 0.25));
  transition: opacity 0.1s linear;
  mix-blend-mode: screen;
}

.low-health-pulse {
  position: absolute;
  inset: 0;
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(255, 0, 38, 0.35) 100%);
  animation: lowHealth 1.1s ease-in-out infinite;
  pointer-events: none;
}

body.is-critical .low-health-pulse {
  opacity: 1;
}

@keyframes lowHealth {
  0%,
  100% { opacity: 0.28; }
  50% { opacity: 0.75; }
}

/* ── shared bits ─────────────────────────────────────────────── */
.micro-label {
  display: block;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.26em;
  color: var(--muted);
  text-transform: uppercase;
}

kbd {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 22px;
  padding: 0 5px;
  border: 1px solid rgba(157, 230, 245, 0.3);
  background: rgba(121, 218, 235, 0.06);
  color: #dffbff;
  font-family: var(--font-body);
  font-size: 10px;
  font-weight: 600;
  line-height: 1;
  box-shadow: inset 0 -2px 0 rgba(0, 0, 0, 0.35);
}

/* ════════════════════════════════════════════════════════════════
   MAIN MENU
   ════════════════════════════════════════════════════════════════ */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 50;
  transition: opacity 0.4s ease, visibility 0.4s ease;
}

.menu-overlay {
  display: flex;
  flex-direction: column;
  padding: calc(var(--pad-y) + env(safe-area-inset-top)) var(--pad-x) calc(var(--pad-y) + env(safe-area-inset-bottom));
  background:
    linear-gradient(90deg, rgba(2, 4, 11, 0.97) 0%, rgba(2, 4, 11, 0.88) 30%, rgba(2, 4, 11, 0.38) 58%, rgba(2, 4, 11, 0.04) 100%),
    linear-gradient(180deg, rgba(2, 4, 11, 0.65) 0%, transparent 24%, transparent 70%, rgba(2, 4, 11, 0.85) 100%);
}

.menu-overlay::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 76% 42%, rgba(57, 238, 255, 0.1), transparent 34%),
    radial-gradient(circle at 63% 80%, rgba(255, 35, 122, 0.08), transparent 28%);
  mix-blend-mode: screen;
}

.menu-grid {
  position: absolute;
  inset: 0;
  opacity: 0.32;
  background-image:
    linear-gradient(rgba(91, 218, 255, 0.055) 1px, transparent 1px),
    linear-gradient(90deg, rgba(91, 218, 255, 0.055) 1px, transparent 1px);
  background-size: 8.333vw 8.333vw;
  mask-image: linear-gradient(90deg, black 0%, transparent 75%);
  pointer-events: none;
}

.menu-grid::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  left: 37%;
  width: 1px;
  background: linear-gradient(transparent, rgba(111, 248, 255, 0.45), transparent);
  transform: skewX(-19deg);
  box-shadow: 0 0 26px rgba(111, 248, 255, 0.3);
}

.menu-header,
.menu-footer,
.menu-main {
  position: relative;
  z-index: 2;
}

.menu-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(111, 248, 255, 0.14);
}

.omni-mark {
  display: flex;
  align-items: center;
  gap: 12px;
}

.omni-mark svg {
  width: 37px;
  height: 37px;
  fill: none;
  stroke: var(--cyan);
  stroke-width: 1.25;
  filter: drop-shadow(0 0 7px rgba(111, 248, 255, 0.45));
}

.omni-mark div {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.omni-mark b {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.25em;
}

.omni-mark span {
  font-size: 8px;
  letter-spacing: 0.23em;
  color: var(--muted);
}

.menu-header-right {
  display: flex;
  align-items: center;
  gap: 18px;
  font-size: 9px;
  letter-spacing: 0.18em;
  color: rgba(205, 235, 246, 0.58);
}

.menu-header-right b {
  color: var(--green);
  font-weight: 600;
}

.live-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 10px var(--green);
  animation: liveDot 1.8s ease-in-out infinite;
}

@keyframes liveDot {
  0%,
  100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.icon-btn {
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  color: var(--muted);
  transition: 0.2s ease;
}

.icon-btn:hover {
  color: var(--cyan);
  border-color: var(--cyan-dim);
  box-shadow: 0 0 18px rgba(111, 248, 255, 0.13);
}

.icon-btn svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.icon-btn .sound-off { display: none; }
body.is-muted .icon-btn .sound-on { display: none; }
body.is-muted .icon-btn .sound-off { display: block; }

.menu-main {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 800px;
  padding: clamp(22px, 4vh, 58px) 0 0;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: clamp(12px, 2.2vh, 25px);
  font-size: clamp(8px, 0.75vw, 11px);
  font-weight: 600;
  letter-spacing: 0.3em;
  color: var(--cyan);
  text-transform: uppercase;
  text-shadow: 0 0 13px rgba(111, 248, 255, 0.4);
}

.eyebrow-line {
  width: clamp(26px, 4vw, 60px);
  height: 1px;
  background: var(--cyan);
  box-shadow: 0 0 10px var(--cyan);
}

.game-title {
  position: relative;
  font-family: var(--font-display);
  font-weight: 800;
  font-size: clamp(70px, 11.6vw, 178px);
  line-height: 0.71;
  letter-spacing: -0.045em;
  text-transform: uppercase;
  width: max-content;
  filter: drop-shadow(0 20px 50px rgba(0, 0, 0, 0.55));
}

.title-line {
  display: block;
  position: relative;
  width: max-content;
}

.line-one {
  color: #eefcff;
  text-shadow:
    0 0 3px #fff,
    0 0 18px rgba(111, 248, 255, 0.52),
    4px 0 0 rgba(255, 45, 135, 0.18),
    -4px 0 0 rgba(37, 160, 255, 0.25);
}

.line-two {
  margin-left: clamp(24px, 5vw, 78px);
  color: #ff3b8f;
  background: linear-gradient(180deg, #fff4fa 0%, #ff9ac6 18%, #ff2d87 55%, #8b0e49 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 0 21px rgba(255, 45, 135, 0.38));
}

.title-line::before {
  content: attr(data-text);
  position: absolute;
  inset: 0;
  color: transparent;
  -webkit-text-stroke: 1px rgba(111, 248, 255, 0.23);
  transform: translate(6px, 2px);
  z-index: -1;
}

.line-two::before {
  -webkit-text-stroke: 1px rgba(255, 45, 135, 0.32);
  transform: translate(8px, -2px);
}

.game-title::after {
  content: "";
  position: absolute;
  left: 1%;
  right: 16%;
  top: 46%;
  height: 2px;
  opacity: 0.52;
  background: linear-gradient(90deg, transparent, rgba(111, 248, 255, 0.9), transparent);
  box-shadow: 0 0 16px var(--cyan);
  animation: titleScan 5.5s ease-in-out infinite;
  pointer-events: none;
}

@keyframes titleScan {
  0%, 100% { transform: translateY(-55px); opacity: 0; }
  8% { opacity: 0.55; }
  18% { transform: translateY(58px); opacity: 0; }
  82% { opacity: 0; }
  92% { opacity: 0.35; transform: translateY(-12px); }
}

.menu-tagline {
  margin-top: clamp(19px, 3.3vh, 35px);
  color: rgba(210, 235, 244, 0.64);
  font-size: clamp(12px, 1.05vw, 16px);
  line-height: 1.55;
  letter-spacing: 0.055em;
  max-width: 470px;
}

.menu-actions {
  display: flex;
  align-items: center;
  gap: clamp(20px, 3vw, 38px);
  margin-top: clamp(24px, 4.2vh, 46px);
}

.primary-btn {
  position: relative;
  display: flex;
  align-items: center;
  gap: 15px;
  min-width: clamp(248px, 21vw, 310px);
  height: clamp(70px, 8.6vh, 86px);
  padding: 0 clamp(20px, 2vw, 28px);
  color: #041016;
  background: linear-gradient(100deg, #eeffff 0%, #78f8ff 30%, #39ddec 100%);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  box-shadow: 0 0 34px rgba(71, 239, 255, 0.24);
  transition: transform 0.18s ease, filter 0.18s ease;
  overflow: hidden;
}

.primary-btn::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 44%;
  left: -60%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.7), transparent);
  transform: skewX(-20deg);
  transition: left 0.5s ease;
}

.primary-btn:hover {
  transform: translateX(5px);
  filter: brightness(1.08) drop-shadow(0 0 18px rgba(93, 242, 255, 0.45));
}

.primary-btn:hover::before {
  left: 120%;
}

.primary-btn:active {
  transform: translateX(5px) scale(0.985);
}

.play-icon {
  width: 35px;
  height: 35px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(2, 25, 32, 0.3);
  flex: 0 0 auto;
}

.play-icon svg {
  width: 17px;
  height: 17px;
  fill: currentColor;
  stroke: none;
}

.play-copy {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  flex: 1;
}

.play-copy b {
  font-family: var(--font-display);
  font-size: clamp(14px, 1.15vw, 18px);
  font-weight: 700;
  letter-spacing: 0.14em;
  line-height: 1;
}

.play-copy small {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.24em;
  opacity: 0.63;
}

.btn-arrow {
  font-size: 19px;
  font-weight: 600;
  opacity: 0.7;
}

.menu-meta {
  display: flex;
  flex-direction: column;
  gap: 9px;
  font-size: 8px;
  letter-spacing: 0.22em;
  color: rgba(205, 232, 242, 0.46);
}

.menu-meta b {
  color: var(--white);
  font-weight: 600;
  font-size: 11px;
  letter-spacing: 0.12em;
}

.controls-deck {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0;
  margin-top: clamp(29px, 4.8vh, 52px);
  border-top: 1px solid rgba(111, 248, 255, 0.13);
  border-bottom: 1px solid rgba(111, 248, 255, 0.13);
  padding: clamp(10px, 1.6vh, 17px) 0;
  width: min(100%, 660px);
}

.control-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 12px;
  border-right: 1px solid rgba(111, 248, 255, 0.09);
}

.control-item:first-child { padding-left: 0; }
.control-item:last-child { border-right: 0; }

.control-item > span:last-child {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.control-item b {
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.15em;
  color: rgba(223, 247, 255, 0.86);
}

.control-item small {
  font-size: 7px;
  letter-spacing: 0.08em;
  color: rgba(191, 222, 232, 0.4);
}

.key-cluster {
  display: flex;
  align-items: center;
  gap: 3px;
  flex: 0 0 auto;
}

.key-cluster kbd {
  min-width: 18px;
  width: 18px;
  height: 18px;
  padding: 0;
  font-size: 8px;
}

.mouse-icon {
  width: 24px;
  height: 31px;
  border: 1px solid rgba(157, 230, 245, 0.38);
  border-radius: 10px;
  position: relative;
  flex: 0 0 auto;
}

.mouse-icon::before {
  content: "";
  position: absolute;
  top: 0;
  bottom: 50%;
  left: 50%;
  width: 1px;
  background: rgba(157, 230, 245, 0.28);
}

.mouse-icon i {
  position: absolute;
  top: 5px;
  left: 50%;
  width: 3px;
  height: 6px;
  margin-left: -1.5px;
  border-radius: 2px;
  background: var(--cyan);
  box-shadow: 0 0 7px var(--cyan);
}

.menu-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 15px;
  border-top: 1px solid rgba(111, 248, 255, 0.1);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: rgba(189, 221, 232, 0.38);
}

.system-status {
  display: flex;
  align-items: center;
  gap: 9px;
}

.system-status em {
  color: rgba(111, 248, 255, 0.35);
  font-style: normal;
}

.status-bars {
  display: flex;
  gap: 2px;
  height: 10px;
  align-items: flex-end;
}

.status-bars i {
  display: block;
  width: 2px;
  background: var(--green);
  box-shadow: 0 0 5px rgba(101, 255, 177, 0.5);
}

.status-bars i:nth-child(1) { height: 4px; }
.status-bars i:nth-child(2) { height: 7px; }
.status-bars i:nth-child(3) { height: 10px; }
.status-bars i:nth-child(4) { height: 6px; }
.status-bars i:nth-child(5) { height: 3px; }

.footer-note span {
  color: var(--pink);
  margin: 0 7px;
}

.menu-side-label {
  position: absolute;
  right: calc(var(--pad-x) + 8px);
  top: 50%;
  z-index: 2;
  transform: translateY(-50%) rotate(90deg);
  transform-origin: center;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.5em;
  color: rgba(111, 248, 255, 0.35);
  white-space: nowrap;
}

.menu-side-label b {
  color: var(--pink);
  margin: 0 7px;
}

.desktop-only { display: inline; }

/* ════════════════════════════════════════════════════════════════
   HUD
   ════════════════════════════════════════════════════════════════ */
.hud {
  position: absolute;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.35s ease;
  padding:
    calc(var(--pad-y) + env(safe-area-inset-top))
    calc(var(--pad-x) + env(safe-area-inset-right))
    calc(var(--pad-y) + env(safe-area-inset-bottom))
    calc(var(--pad-x) + env(safe-area-inset-left));
}

.hud-top {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: start;
  gap: 24px;
}

.brand-mini {
  display: flex;
  align-items: center;
  gap: 11px;
}

.brand-sigil {
  width: 30px;
  height: 35px;
  display: flex;
  align-items: flex-end;
  gap: 3px;
  padding-bottom: 2px;
}

.brand-sigil span {
  width: 5px;
  background: var(--cyan);
  box-shadow: 0 0 8px rgba(111, 248, 255, 0.6);
  transform: skewY(-18deg);
}

.brand-sigil span:nth-child(1) { height: 12px; opacity: 0.5; }
.brand-sigil span:nth-child(2) { height: 24px; }
.brand-sigil span:nth-child(3) { height: 34px; opacity: 0.75; }

.brand-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.brand-copy b {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.2em;
}

.brand-copy span {
  font-size: 7px;
  letter-spacing: 0.2em;
  color: var(--muted);
}

.brand-copy i {
  font-style: normal;
  color: var(--pink);
  margin: 0 3px;
}

.wave-module {
  text-align: center;
  min-width: 178px;
  position: relative;
}

.wave-module::before,
.wave-module::after {
  content: "";
  position: absolute;
  top: 20px;
  width: 34px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--cyan-dim));
}

.wave-module::before { left: -30px; }
.wave-module::after { right: -30px; transform: scaleX(-1); }

.wave-line {
  display: flex;
  align-items: baseline;
  justify-content: center;
  gap: 8px;
  line-height: 1;
  margin-top: 3px;
}

.wave-line em {
  font-style: normal;
  font-size: 9px;
  letter-spacing: 0.22em;
  color: var(--cyan);
}

.wave-line b {
  font-family: var(--font-display);
  font-size: 34px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: var(--white);
  text-shadow: 0 0 16px rgba(111, 248, 255, 0.3);
}

.wave-ticks {
  display: flex;
  align-items: center;
  gap: 3px;
  margin-left: 2px;
}

.wave-ticks i {
  width: 2px;
  height: 6px;
  background: rgba(111, 248, 255, 0.2);
}

.wave-ticks i.on {
  background: var(--cyan);
  box-shadow: 0 0 6px var(--cyan);
}

.wave-sub {
  display: block;
  margin-top: 4px;
  font-size: 7px;
  letter-spacing: 0.24em;
  color: rgba(199, 231, 240, 0.48);
  text-transform: uppercase;
}

.hud-top-right {
  display: flex;
  justify-content: flex-end;
  align-items: flex-start;
  gap: 19px;
}

.score-stack {
  text-align: right;
  padding-top: 1px;
}

.score-stack > b {
  display: block;
  font-family: var(--font-display);
  font-size: clamp(24px, 2.3vw, 36px);
  font-weight: 600;
  letter-spacing: 0.07em;
  line-height: 1.08;
  color: var(--white);
  text-shadow: 0 0 17px rgba(111, 248, 255, 0.22);
  font-variant-numeric: tabular-nums;
}

.combo {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 2px;
  font-size: 7px;
  letter-spacing: 0.17em;
  color: rgba(196, 228, 238, 0.5);
  transition: color 0.2s ease, transform 0.2s ease;
}

.combo b {
  color: var(--pink-bright);
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.combo i {
  display: block;
  width: 25px;
  height: 2px;
  background: linear-gradient(90deg, var(--pink), transparent);
  transform-origin: left center;
  transition: transform 0.12s linear;
}

.combo.is-hot {
  color: var(--pink);
  transform: scale(1.05);
}

.combo.is-hot b {
  text-shadow: 0 0 12px rgba(255, 45, 135, 0.75);
}

.radar-wrap {
  position: relative;
  width: clamp(106px, 10.5vw, 144px);
  height: clamp(106px, 10.5vw, 144px);
  border: 1px solid rgba(111, 248, 255, 0.18);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(4, 24, 32, 0.68), rgba(3, 9, 16, 0.5) 68%);
  box-shadow:
    inset 0 0 22px rgba(15, 85, 105, 0.16),
    0 0 25px rgba(0, 0, 0, 0.3);
  overflow: hidden;
}

#radar {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.radar-label {
  position: absolute;
  left: 50%;
  bottom: 4px;
  transform: translateX(-50%);
  font-size: 6px;
  letter-spacing: 0.23em;
  color: rgba(111, 248, 255, 0.45);
  white-space: nowrap;
}

.radar-sweep {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  background: conic-gradient(from 0deg, transparent 0 305deg, rgba(111, 248, 255, 0.04) 320deg, rgba(111, 248, 255, 0.2) 356deg, transparent 360deg);
  animation: radarSweep 4s linear infinite;
}

@keyframes radarSweep {
  to { transform: rotate(360deg); }
}

/* kill feed */
.kill-feed {
  position: absolute;
  top: 145px;
  right: calc(var(--pad-x) + env(safe-area-inset-right));
  width: 230px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 5px;
}

.feed-item {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 8px;
  border-right: 2px solid var(--pink);
  background: linear-gradient(90deg, transparent, rgba(4, 11, 20, 0.72));
  font-size: 8px;
  letter-spacing: 0.12em;
  color: rgba(219, 242, 249, 0.7);
  animation: feedIn 0.2s ease both;
  white-space: nowrap;
}

.feed-item b { color: var(--white); font-weight: 600; }
.feed-item em { color: var(--pink-bright); font-style: normal; }
.feed-item .feed-score { color: var(--cyan); font-family: var(--font-display); font-size: 10px; }

@keyframes feedIn {
  from { opacity: 0; transform: translateX(12px); }
}

/* center alert */
.center-alert {
  position: absolute;
  left: 50%;
  top: 27%;
  transform: translateX(-50%);
  text-align: center;
  opacity: 0;
  min-width: 360px;
  pointer-events: none;
}

.center-alert.show {
  animation: alertFlash 3s ease both;
}

@keyframes alertFlash {
  0% { opacity: 0; transform: translate(-50%, 7px); filter: blur(6px); }
  6% { opacity: 1; transform: translate(-50%, 0); filter: blur(0); }
  12% { opacity: 0.55; }
  16% { opacity: 1; }
  74% { opacity: 1; }
  100% { opacity: 0; }
}

.center-alert span {
  display: block;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.45em;
  color: var(--cyan);
  text-shadow: 0 0 12px rgba(111, 248, 255, 0.7);
}

.center-alert strong {
  display: block;
  margin: 4px 0 3px;
  font-family: var(--font-display);
  font-size: clamp(42px, 4.8vw, 66px);
  line-height: 0.95;
  font-weight: 700;
  letter-spacing: 0.02em;
  color: var(--white);
  text-shadow: 0 0 24px rgba(51, 222, 255, 0.3), 0 4px 0 rgba(0, 0, 0, 0.32);
}

.center-alert small {
  font-size: 8px;
  letter-spacing: 0.3em;
  color: rgba(218, 241, 248, 0.55);
}

.center-alert.danger span,
.center-alert.danger strong {
  color: var(--pink-bright);
  text-shadow: 0 0 22px rgba(255, 45, 135, 0.48);
}

.center-alert.clear span,
.center-alert.clear strong {
  color: var(--green);
  text-shadow: 0 0 22px rgba(101, 255, 177, 0.4);
}

.objective-chip {
  position: absolute;
  left: 50%;
  top: 103px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: rgba(210, 237, 244, 0.56);
  background: rgba(3, 9, 17, 0.38);
  border: 1px solid rgba(111, 248, 255, 0.1);
  padding: 4px 9px;
  white-space: nowrap;
}

.objective-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 7px var(--cyan);
}

/* crosshair */
.crosshair {
  --spread: 0px;
  position: absolute;
  left: 50%;
  top: 50%;
  width: 0;
  height: 0;
  z-index: 3;
  transition: opacity 0.2s ease;
}

.crosshair.is-ads .ch-ring {
  transform: translate(-50%, -50%) scale(0.65);
  opacity: 0.85;
}

.crosshair.is-ads .ch {
  opacity: 0.55;
}

.ch {
  position: absolute;
  background: rgba(226, 254, 255, 0.92);
  box-shadow: 0 0 5px rgba(111, 248, 255, 0.9), 0 0 12px rgba(111, 248, 255, 0.3);
  transition: transform 0.09s ease-out, opacity 0.2s ease;
}

.ch-t,
.ch-b {
  width: 2px;
  height: 8px;
  left: -1px;
}

.ch-l,
.ch-r {
  width: 8px;
  height: 2px;
  top: -1px;
}

.ch-t { top: calc(-11px - var(--spread)); }
.ch-b { top: calc(3px + var(--spread)); }
.ch-l { left: calc(-11px - var(--spread)); }
.ch-r { left: calc(3px + var(--spread)); }

.ch-dot {
  position: absolute;
  left: -2px;
  top: -2px;
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 6px var(--cyan), 0 0 13px rgba(111, 248, 255, 0.55);
}

.ch-ring {
  position: absolute;
  left: 0;
  top: 0;
  width: 27px;
  height: 27px;
  border: 1px solid rgba(111, 248, 255, 0.22);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  transition: transform 0.18s ease, opacity 0.2s ease;
}

.crosshair.recoil .ch-t { transform: translateY(-3px); }
.crosshair.recoil .ch-b { transform: translateY(3px); }
.crosshair.recoil .ch-l { transform: translateX(-3px); }
.crosshair.recoil .ch-r { transform: translateX(3px); }

.hitmarker {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  opacity: 0;
  transform: scale(0.65);
}

.hitmarker.show {
  animation: hitMark 0.25s ease-out both;
}

.hitmarker.kill i {
  background: var(--pink);
  box-shadow: 0 0 8px var(--pink);
}

@keyframes hitMark {
  0% { opacity: 1; transform: scale(0.7); }
  18% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(1.12); }
}

.hitmarker i {
  position: absolute;
  width: 7px;
  height: 1.5px;
  background: #fff;
  box-shadow: 0 0 5px var(--cyan);
}

.hitmarker i:nth-child(1) { left: -13px; top: -9px; transform: rotate(45deg); }
.hitmarker i:nth-child(2) { left: 6px; top: -9px; transform: rotate(-45deg); }
.hitmarker i:nth-child(3) { left: -13px; top: 8px; transform: rotate(-45deg); }
.hitmarker i:nth-child(4) { left: 6px; top: 8px; transform: rotate(45deg); }

.reload-hint {
  position: absolute;
  left: 50%;
  top: calc(50% + 61px);
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 5px 9px;
  opacity: 0;
  background: rgba(3, 8, 16, 0.7);
  border: 1px solid rgba(255, 193, 92, 0.3);
  transition: opacity 0.2s ease;
  color: var(--amber);
  font-size: 8px;
  letter-spacing: 0.18em;
  animation: reloadPulse 1.1s ease-in-out infinite;
}

.reload-hint.show { opacity: 1; }
.reload-hint kbd { border-color: rgba(255, 193, 92, 0.45); color: var(--amber); }

@keyframes reloadPulse {
  50% { border-color: rgba(255, 193, 92, 0.7); box-shadow: 0 0 15px rgba(255, 193, 92, 0.12); }
}

.damage-arc {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 240px;
  height: 240px;
  margin: -120px 0 0 -120px;
  border-radius: 50%;
  border-top: 2px solid rgba(255, 38, 74, 0.85);
  filter: drop-shadow(0 0 9px rgba(255, 25, 65, 0.8));
  opacity: 0;
  pointer-events: none;
}

.damage-arc.flash {
  animation: damageArc 0.55s ease-out both;
}

@keyframes damageArc {
  0% { opacity: 1; transform: scale(0.9); }
  100% { opacity: 0; transform: scale(1.08); }
}

/* bottom HUD */
.hud-bottom {
  position: absolute;
  left: calc(var(--pad-x) + env(safe-area-inset-left));
  right: calc(var(--pad-x) + env(safe-area-inset-right));
  bottom: calc(var(--pad-y) + env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: end;
  gap: 24px;
}

.vitals-panel {
  width: min(290px, 30vw);
  position: relative;
  padding: 11px 14px 10px;
  background:
    linear-gradient(100deg, rgba(6, 15, 26, 0.85), rgba(5, 12, 22, 0.42) 70%, transparent),
    linear-gradient(0deg, rgba(111, 248, 255, 0.03), transparent);
  border-left: 2px solid rgba(111, 248, 255, 0.62);
  clip-path: polygon(0 0, 100% 0, 100% 70%, calc(100% - 14px) 100%, 0 100%);
}

.vitals-panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  right: 12px;
  height: 1px;
  background: linear-gradient(90deg, var(--cyan-dim), transparent);
}

.vitals-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 6px;
}

.operator-tag {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.19em;
  color: rgba(208, 240, 247, 0.62);
}

.operator-tag i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 6px var(--green);
}

.shield-readout {
  font-size: 6px;
  letter-spacing: 0.16em;
  color: rgba(111, 248, 255, 0.52);
}

.shield-readout b {
  font-family: var(--font-display);
  font-size: 13px;
  color: var(--cyan);
  font-weight: 600;
}

.shield-track {
  position: relative;
  height: 5px;
  background: rgba(111, 248, 255, 0.1);
  overflow: hidden;
  transform: skewX(-20deg);
  margin-bottom: 9px;
}

.shield-track i {
  display: block;
  height: 100%;
  width: 50%;
  background: linear-gradient(90deg, #2a9cb0, var(--cyan));
  box-shadow: 0 0 10px rgba(111, 248, 255, 0.6);
  transition: width 0.18s ease;
}

.shield-track span {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 24px, rgba(2, 9, 16, 0.82) 24px 27px);
}

.health-row {
  display: flex;
  align-items: flex-end;
  gap: 15px;
}

.health-number {
  display: flex;
  align-items: flex-start;
  line-height: 0.85;
  min-width: 80px;
}

.health-number span {
  color: var(--pink);
  font-family: var(--font-display);
  font-size: 17px;
  margin-top: 1px;
  text-shadow: 0 0 10px rgba(255, 45, 135, 0.6);
}

.health-number b {
  font-family: var(--font-display);
  font-size: clamp(34px, 3.2vw, 48px);
  font-weight: 600;
  letter-spacing: -0.05em;
  color: var(--white);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 17px rgba(111, 248, 255, 0.18);
}

.health-meta {
  flex: 1;
  padding-bottom: 3px;
}

.health-track {
  height: 4px;
  margin-top: 5px;
  background: rgba(111, 248, 255, 0.1);
  overflow: hidden;
  transform: skewX(-20deg);
}

.health-track i {
  display: block;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, #ff2d87, #ff8fba 55%, #f4ffff);
  box-shadow: 0 0 10px rgba(255, 45, 135, 0.5);
  transition: width 0.18s ease, background 0.2s ease;
}

body.is-critical .health-track i {
  background: linear-gradient(90deg, #ff1f38, #ff7b57);
  animation: lowHealth 0.8s ease-in-out infinite;
}

body.is-critical .health-number b {
  color: #ff9a9f;
  text-shadow: 0 0 20px rgba(255, 30, 60, 0.65);
}

.combat-hints {
  display: flex;
  gap: 13px;
  padding-bottom: 8px;
  font-size: 6px;
  letter-spacing: 0.14em;
  color: rgba(197, 226, 235, 0.32);
}

.combat-hints span {
  display: flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.combat-hints kbd {
  min-width: 16px;
  height: 15px;
  padding: 0 3px;
  font-size: 6px;
  border-color: rgba(157, 230, 245, 0.14);
  color: rgba(200, 237, 244, 0.44);
}

.weapon-panel {
  justify-self: end;
  width: min(260px, 27vw);
  text-align: right;
  padding: 9px 0 8px 20px;
  border-right: 2px solid rgba(255, 45, 135, 0.6);
  background: linear-gradient(270deg, rgba(7, 12, 23, 0.78), transparent 76%);
  position: relative;
}

.weapon-panel::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 140px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 45, 135, 0.55));
}

.weapon-topline {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 13px;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: rgba(200, 230, 240, 0.45);
}

.weapon-mode {
  color: var(--cyan);
  font-size: 6px;
}

.weapon-serial {
  font-family: var(--font-display);
  font-size: 9px;
  color: rgba(255, 114, 173, 0.62);
}

.ammo-row {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 5px;
  line-height: 0.8;
  margin: 3px 0 6px;
}

.ammo-row b {
  font-family: var(--font-display);
  font-size: clamp(40px, 4.5vw, 64px);
  font-weight: 600;
  letter-spacing: -0.04em;
  color: var(--white);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 20px rgba(111, 248, 255, 0.18);
}

.ammo-row b.low {
  color: var(--amber);
  text-shadow: 0 0 20px rgba(255, 193, 92, 0.36);
}

.ammo-row b.empty {
  color: var(--danger);
  text-shadow: 0 0 20px rgba(255, 77, 94, 0.45);
  animation: lowHealth 0.5s linear infinite;
}

.ammo-divider {
  color: rgba(255, 114, 173, 0.45);
  font-size: 18px;
  font-weight: 300;
}

.ammo-row > span:last-child {
  font-family: var(--font-display);
  font-size: 17px;
  color: rgba(211, 236, 244, 0.52);
  font-variant-numeric: tabular-nums;
}

.reload-track {
  width: 100%;
  height: 2px;
  background: rgba(255, 45, 135, 0.12);
  overflow: hidden;
}

.reload-track i {
  display: block;
  width: 0%;
  height: 100%;
  background: linear-gradient(90deg, var(--pink), var(--cyan));
  box-shadow: 0 0 8px rgba(111, 248, 255, 0.5);
  transition: width 0.05s linear;
}

.weapon-name {
  margin-top: 5px;
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.2em;
  color: rgba(207, 236, 245, 0.38);
}

.weapon-name span {
  color: rgba(255, 114, 173, 0.55);
  margin-left: 4px;
}

/* toasts */
.toast-stack {
  position: absolute;
  left: 50%;
  bottom: 23%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.toast {
  padding: 5px 12px;
  border: 1px solid rgba(111, 248, 255, 0.2);
  background: rgba(3, 10, 19, 0.8);
  font-size: 8px;
  letter-spacing: 0.2em;
  color: var(--cyan);
  animation: toastUp 2.4s ease both;
  white-space: nowrap;
}

.toast.pink { color: var(--pink-bright); border-color: rgba(255, 45, 135, 0.28); }
.toast.amber { color: var(--amber); border-color: rgba(255, 193, 92, 0.28); }
.toast.green { color: var(--green); border-color: rgba(101, 255, 177, 0.25); }

@keyframes toastUp {
  0% { opacity: 0; transform: translateY(6px); }
  10%, 78% { opacity: 1; transform: translateY(0); }
  100% { opacity: 0; transform: translateY(-12px); }
}

/* ════════════════════════════════════════════════════════════════
   PAUSE + GAME OVER
   ════════════════════════════════════════════════════════════════ */
.pause-overlay,
.gameover-overlay {
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle at 50% 45%, rgba(7, 22, 33, 0.75), rgba(2, 4, 10, 0.92) 68%),
    rgba(2, 4, 10, 0.6);
  backdrop-filter: blur(7px);
}

.pause-panel,
.gameover-panel {
  width: min(570px, calc(100vw - 40px));
  padding: clamp(26px, 4vw, 48px);
  border: 1px solid rgba(111, 248, 255, 0.16);
  background:
    linear-gradient(140deg, rgba(10, 25, 39, 0.85), rgba(4, 9, 18, 0.92)),
    repeating-linear-gradient(90deg, transparent 0 34px, rgba(111, 248, 255, 0.03) 34px 35px);
  position: relative;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.55);
}

.pause-panel::before,
.gameover-panel::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 34%;
  height: 2px;
  background: var(--cyan);
  box-shadow: 0 0 16px var(--cyan);
}

.gameover-panel::before {
  background: var(--pink);
  box-shadow: 0 0 16px var(--pink);
}

.panel-kicker {
  display: block;
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.35em;
  color: var(--cyan);
  margin-bottom: 7px;
}

.panel-kicker.danger { color: var(--pink-bright); }

.pause-panel h2,
.gameover-panel h2 {
  font-family: var(--font-display);
  font-size: clamp(44px, 6vw, 76px);
  line-height: 0.86;
  font-weight: 700;
  letter-spacing: -0.035em;
}

.pause-panel h2 { margin-bottom: 14px; }

.gameover-panel h2 span {
  color: var(--pink);
  text-shadow: 0 0 24px rgba(255, 45, 135, 0.45);
}

.pause-panel p,
.gameover-panel > p {
  max-width: 390px;
  color: rgba(204, 231, 239, 0.56);
  font-size: 11px;
  line-height: 1.6;
  letter-spacing: 0.03em;
  margin-bottom: 23px;
}

.pause-actions,
.gameover-actions {
  display: flex;
  align-items: center;
  gap: 18px;
  flex-wrap: wrap;
}

.primary-btn.compact {
  min-width: 214px;
  height: 66px;
  padding: 0 18px;
  gap: 11px;
}

.primary-btn.compact .play-icon {
  width: 29px;
  height: 29px;
}

.primary-btn.compact .play-copy b { font-size: 13px; }
.primary-btn.compact .play-copy small { font-size: 7px; }

.ghost-btn {
  height: 66px;
  padding: 0 22px;
  border: 1px solid rgba(111, 248, 255, 0.18);
  color: rgba(207, 236, 244, 0.55);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.21em;
  transition: 0.2s ease;
}

.ghost-btn:hover {
  color: var(--white);
  border-color: rgba(255, 45, 135, 0.44);
  background: rgba(255, 45, 135, 0.06);
}

.pause-stats {
  display: flex;
  gap: 28px;
  margin-top: 25px;
  padding-top: 15px;
  border-top: 1px solid rgba(111, 248, 255, 0.1);
  font-size: 7px;
  letter-spacing: 0.18em;
  color: rgba(195, 226, 236, 0.4);
}

.pause-stats b {
  display: block;
  margin-top: 3px;
  font-family: var(--font-display);
  font-size: 17px;
  color: var(--white);
  letter-spacing: 0.03em;
}

.result-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1px;
  background: rgba(111, 248, 255, 0.09);
  border: 1px solid rgba(111, 248, 255, 0.12);
  margin-bottom: 21px;
}

.result-grid div {
  background: rgba(4, 10, 19, 0.9);
  padding: 13px 16px;
}

.result-grid span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.19em;
  color: rgba(193, 226, 236, 0.42);
}

.result-grid b {
  display: block;
  font-family: var(--font-display);
  font-size: 25px;
  font-weight: 600;
  color: var(--white);
  margin-top: 1px;
  font-variant-numeric: tabular-nums;
}

.result-grid div:first-child b { color: var(--cyan); }

.best-line {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: -4px 0 18px;
  color: var(--amber);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.26em;
  animation: liveDot 1.4s ease-in-out infinite;
}

.best-line span { font-size: 11px; }

/* ════════════════════════════════════════════════════════════════
   TOUCH CONTROLS
   ════════════════════════════════════════════════════════════════ */
.touch-controls {
  position: absolute;
  inset: 0;
  z-index: 20;
  pointer-events: none;
  display: none;
  transition: opacity 0.3s ease;
}

body.is-touch .touch-controls { display: block; }

.stick-zone {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: max(18px, env(safe-area-inset-bottom));
  width: 160px;
  height: 160px;
  pointer-events: auto;
  touch-action: none;
  z-index: 2;
}

.stick-base {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 126px;
  height: 126px;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(111, 248, 255, 0.2);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(8, 22, 32, 0.44), rgba(4, 10, 19, 0.2) 65%, transparent 70%);
  box-shadow: inset 0 0 30px rgba(111, 248, 255, 0.05);
}

.stick-rings {
  position: absolute;
  inset: 17px;
  border: 1px dashed rgba(111, 248, 255, 0.15);
  border-radius: 50%;
}

.stick-thumb {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 50px;
  height: 50px;
  margin: -25px 0 0 -25px;
  border: 1px solid rgba(111, 248, 255, 0.55);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(111, 248, 255, 0.23), rgba(111, 248, 255, 0.04) 65%);
  box-shadow: 0 0 18px rgba(111, 248, 255, 0.17);
}

.touch-look {
  position: absolute;
  right: 0;
  top: 15%;
  bottom: 0;
  width: 58%;
  pointer-events: auto;
  touch-action: none;
}

.touch-btn {
  pointer-events: auto;
  touch-action: none;
  display: grid;
  place-items: center;
  border: 1px solid rgba(111, 248, 255, 0.3);
  border-radius: 50%;
  background: radial-gradient(circle, rgba(17, 47, 58, 0.52), rgba(4, 10, 19, 0.32));
  color: rgba(222, 252, 255, 0.85);
  font-family: var(--font-display);
  box-shadow: inset 0 0 23px rgba(111, 248, 255, 0.06);
  backdrop-filter: blur(2px);
}

.touch-btn:active,
.touch-btn.is-down {
  border-color: var(--cyan);
  background: radial-gradient(circle, rgba(74, 204, 220, 0.44), rgba(4, 10, 19, 0.4));
  box-shadow: 0 0 25px rgba(111, 248, 255, 0.22), inset 0 0 25px rgba(111, 248, 255, 0.12);
}

.fire-btn {
  position: absolute;
  right: max(24px, env(safe-area-inset-right));
  bottom: max(26px, env(safe-area-inset-bottom));
  width: 104px;
  height: 104px;
  font-size: 9px;
  letter-spacing: 0.2em;
}

.fire-btn span {
  position: absolute;
  inset: 12px;
  border: 1px solid rgba(255, 45, 135, 0.33);
  border-radius: 50%;
}

.fire-btn b {
  font-weight: 600;
  z-index: 1;
}

.small-btn {
  width: 50px;
  height: 50px;
  font-size: 13px;
  letter-spacing: 0;
}

#touch-reload { position: absolute; right: 142px; bottom: max(43px, calc(env(safe-area-inset-bottom) + 17px)); }
#touch-jump { position: absolute; right: max(43px, calc(env(safe-area-inset-right) + 19px)); bottom: 145px; }
#touch-ads { position: absolute; right: 142px; bottom: 105px; }

/* ════════════════════════════════════════════════════════════════
   LOADER, ROTATE HINT, RESPONSIVE
   ════════════════════════════════════════════════════════════════ */
.loading-screen {
  position: absolute;
  inset: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 13px;
  background: #03050b;
  transition: opacity 0.7s ease, visibility 0.7s ease;
}

.loading-screen.done {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.loading-screen > span {
  font-size: 8px;
  letter-spacing: 0.38em;
  color: rgba(111, 248, 255, 0.68);
}

.loader-mark {
  display: flex;
  align-items: flex-end;
  gap: 5px;
  height: 42px;
}

.loader-mark i {
  width: 5px;
  height: 17px;
  background: var(--cyan);
  box-shadow: 0 0 12px var(--cyan);
  animation: loaderBars 0.9s ease-in-out infinite alternate;
}

.loader-mark i:nth-child(2) { height: 32px; animation-delay: 0.18s; }
.loader-mark i:nth-child(3) { height: 24px; animation-delay: 0.36s; }

@keyframes loaderBars {
  to { transform: scaleY(0.5); opacity: 0.5; }
}

.loader-track {
  width: 170px;
  height: 1px;
  background: rgba(111, 248, 255, 0.12);
  overflow: hidden;
}

.loader-track i {
  display: block;
  width: 45%;
  height: 100%;
  background: var(--cyan);
  box-shadow: 0 0 9px var(--cyan);
  animation: loaderTrack 1.1s ease-in-out infinite;
}

@keyframes loaderTrack {
  0% { transform: translateX(-110%); }
  100% { transform: translateX(380%); }
}

.rotate-hint {
  position: absolute;
  inset: 0;
  z-index: 80;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 9px;
  background: rgba(2, 4, 10, 0.9);
  backdrop-filter: blur(7px);
  text-align: center;
}

.rotate-hint span {
  font-size: 34px;
  color: var(--cyan);
  animation: rotateNudge 2s ease-in-out infinite;
}

.rotate-hint b {
  font-family: var(--font-display);
  font-size: 18px;
  letter-spacing: 0.15em;
}

.rotate-hint small {
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--muted);
}

@keyframes rotateNudge {
  0%, 100% { transform: rotate(0deg); }
  50% { transform: rotate(90deg); }
}

/* ── responsive ─────────────────────────────────────────────── */
@media (max-width: 900px) {
  .menu-main { max-width: 610px; }
  .controls-deck { grid-template-columns: repeat(2, 1fr); row-gap: 10px; width: 100%; }
  .control-item:nth-child(2) { border-right: 0; }
  .hud-top { gap: 12px; }
  .combat-hints { display: none; }
  .hud-bottom { grid-template-columns: 1fr 1fr; }
  .vitals-panel { width: min(260px, 42vw); }
  .weapon-panel { width: min(230px, 39vw); }
  .objective-chip { top: 92px; }
}

@media (max-width: 700px) {
  :root { --pad-x: 15px; --pad-y: 13px; }
  .menu-header-right > span:not(.live-dot) { display: none; }
  .menu-header-right { gap: 8px; }
  .menu-main { padding-top: 12px; }
  .game-title { font-size: clamp(58px, 17.5vw, 112px); }
  .line-two { margin-left: 20px; }
  .menu-tagline { font-size: 11px; max-width: 350px; }
  .menu-tagline br { display: none; }
  .menu-actions { flex-direction: column; align-items: flex-start; gap: 16px; margin-top: 23px; }
  .primary-btn { width: 100%; min-width: 0; }
  .menu-meta { flex-direction: row; gap: 24px; }
  .controls-deck { display: none; }
  .menu-footer { font-size: 6px; }
  .footer-note { display: none; }
  .menu-side-label { display: none; }
  .brand-copy span { display: none; }
  .brand-copy b { font-size: 10px; letter-spacing: 0.13em; }
  .brand-sigil { width: 22px; height: 27px; }
  .brand-sigil span:nth-child(3) { height: 26px; }
  .wave-module { min-width: 120px; }
  .wave-line b { font-size: 27px; }
  .wave-module::before,
  .wave-module::after { width: 15px; }
  .wave-module::before { left: -12px; }
  .wave-module::after { right: -12px; }
  .score-stack > b { font-size: 21px; }
  .radar-wrap { width: 88px; height: 88px; }
  .hud-top-right { gap: 10px; }
  .hud-top { grid-template-columns: 1fr auto auto; gap: 8px; }
  .hud-top-right { flex-direction: row-reverse; align-items: center; }
  .score-stack { padding-top: 0; }
  .combo { display: none; }
  .kill-feed { display: none; }
  .objective-chip { display: none; }
  .vitals-panel { width: min(220px, 46vw); padding: 7px 9px; }
  .health-number { min-width: 57px; }
  .health-number b { font-size: 31px; }
  .shield-readout { display: none; }
  .weapon-panel { width: min(190px, 42vw); }
  .ammo-row b { font-size: 38px; }
  .weapon-topline, .weapon-name { display: none; }
  .hud-bottom { gap: 8px; left: 15px; right: 15px; }
  .center-alert { top: 24%; min-width: 270px; }
  .center-alert strong { font-size: 38px; }
  .result-grid { grid-template-columns: 1fr 1fr; }
  .pause-panel, .gameover-panel { padding: 25px 22px; }
  .pause-actions, .gameover-actions { gap: 10px; }
  .primary-btn.compact { min-width: 190px; height: 58px; }
  .ghost-btn { height: 58px; }
  .touch-controls { display: block; }
}

@media (max-width: 430px) {
  .menu-header .omni-mark span { display: none; }
  .game-title { font-size: 17.2vw; }
  .menu-meta { flex-direction: column; gap: 5px; }
  .pause-stats { gap: 16px; }
  .result-grid b { font-size: 20px; }
  .fire-btn { width: 88px; height: 88px; }
  .small-btn { width: 44px; height: 44px; }
  #touch-reload { right: 122px; bottom: 33px; }
  #touch-ads { right: 122px; bottom: 88px; }
  #touch-jump { right: 34px; bottom: 125px; }
}

@media (pointer: coarse) {
  .touch-controls { display: block; }
  .combat-hints { display: none; }
  .menu-footer .footer-note { display: none; }
}

@media (orientation: portrait) and (pointer: coarse) and (max-width: 700px) {
  body.in-game .rotate-hint { display: flex; }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
  }
}

/* Synthesised combat audio — no external samples. */

const clampGain = (v) => Math.max(0.0001, Math.min(1, v));

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.enabled = true;
    this.noiseBuffer = null;
    this.ambientGain = null;
    this.ambientStarted = false;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === "suspended") this.ctx.resume();
      return;
    }

    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;

    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.42 : 0;
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 20;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.22;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);

    const len = Math.floor(this.ctx.sampleRate * 1.2);
    this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

    this.startAmbience();
  }

  setEnabled(on) {
    this.enabled = on;
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.linearRampToValueAtTime(on ? 0.42 : 0.0001, this.ctx.currentTime + 0.08);
    }
  }

  resume() {
    if (this.ctx && this.ctx.state === "suspended") this.ctx.resume();
  }

  get t() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  startAmbience() {
    if (!this.ctx || this.ambientStarted) return;
    this.ambientStarted = true;

    this.ambientGain = this.ctx.createGain();
    this.ambientGain.gain.value = 0.055;

    const filter = this.ctx.createBiquadFilter();
    filter.type = "lowpass";
    filter.frequency.value = 240;
    filter.Q.value = 2.5;

    const freqs = [41.2, 55, 82.4, 110];
    freqs.forEach((f, i) => {
      const osc = this.ctx.createOscillator();
      osc.type = i % 2 ? "triangle" : "sine";
      osc.frequency.value = f;
      const g = this.ctx.createGain();
      g.gain.value = 0.2 / (i + 1);
      osc.connect(g);
      g.connect(filter);
      osc.start();
    });

    const lfo = this.ctx.createOscillator();
    lfo.frequency.value = 0.065;
    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 100;
    lfo.connect(lfoGain);
    lfoGain.connect(filter.frequency);
    lfo.start();

    filter.connect(this.ambientGain);
    this.ambientGain.connect(this.master);
  }

  tone(opts) {
    if (!this.ctx || !this.enabled) return;
    const {
      type = "sine",
      freq = 440,
      endFreq = null,
      dur = 0.15,
      vol = 0.2,
      attack = 0.004,
      release = dur,
      delay = 0,
      filter = null,
      q = 1,
      pan = 0,
    } = opts;

    const t0 = this.t + delay;
    const osc = this.ctx.createOscillator();
    const gain = this.ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(Math.max(20, freq), t0);
    if (endFreq != null) {
      osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t0 + dur);
    }

    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(clampGain(vol), t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + Math.max(attack + 0.01, release));

    let node = gain;
    if (filter != null) {
      const bq = this.ctx.createBiquadFilter();
      bq.type = "lowpass";
      bq.frequency.setValueAtTime(filter, t0);
      bq.Q.value = q;
      gain.connect(bq);
      node = bq;
