import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl'] });
const failures = [];
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  page.on('pageerror', e => failures.push(e.message));
  page.on('console', m => { if (m.type() === 'error') failures.push(m.text()); });
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.waitForTimeout(1200);
  console.log('menu', await page.locator('#menu').evaluate(e => !e.classList.contains('is-hidden')));
  await page.locator('#sound-btn').click();
  console.log('sound-toggle-pressed', await page.locator('#sound-btn').getAttribute('aria-pressed'));
  await page.locator('#play-btn').click();
  await page.waitForTimeout(1500);
  console.log('started', await page.locator('#hud').evaluate(e => !e.classList.contains('is-hidden')), 'wave', await page.locator('#wave-num').innerText());
  await page.keyboard.press('KeyP');
  console.log('paused', await page.locator('#pause').evaluate(e => !e.classList.contains('is-hidden')));
  await page.locator('#resume-btn').click();
  console.log('resumed', await page.locator('#pause').evaluate(e => e.classList.contains('is-hidden')));
  await page.keyboard.press('KeyP');
  await page.locator('#quit-btn').click();
  console.log('returned-menu', await page.locator('#menu').evaluate(e => !e.classList.contains('is-hidden')));
  await page.locator('#play-btn').click();
  await page.waitForTimeout(900);
  await page.locator('#game-canvas').screenshot({ path: '/tmp/opencode/neon-breach-latest.jpg', type: 'jpeg', quality: 72 });
  await page.keyboard.press('KeyR');
  await page.keyboard.press('Space');
  await page.keyboard.down('KeyW'); await page.waitForTimeout(250); await page.keyboard.up('KeyW');
  await page.mouse.down(); await page.waitForTimeout(250); await page.mouse.up();
  console.log('desktop-final', await page.locator('#hud').evaluate(e => !e.classList.contains('is-hidden')), 'errors', failures);
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  mobile.on('pageerror', e => failures.push('mobile: ' + e.message));
  await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
  await mobile.waitForTimeout(700);
  await mobile.locator('#play-btn').click();
  await mobile.waitForTimeout(300);
  console.log('touch-controls-visible', await mobile.locator('#touch-controls').evaluate(e => !e.classList.contains('is-hidden')));
  await mobile.locator('#touch-fire').tap();
  await mobile.locator('#touch-reload').tap();
  await mobile.locator('#touch-jump').tap();
  await mobile.locator('#touch-ads').tap();
  await mobile.locator('#touch-pause').tap();
  console.log('touch-paused', await mobile.locator('#pause').evaluate(e => !e.classList.contains('is-hidden')));
  await mobile.locator('#resume-btn').tap();
  console.log('touch-resumed', await mobile.locator('#pause').evaluate(e => e.classList.contains('is-hidden')), 'errors', failures);
  await mobile.close();
  await page.close();
} finally { await browser.close(); }

