import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl'] });
const failures = [], missing = [];
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  page.on('pageerror', e => failures.push(e.message));
  page.on('console', m => { if (m.type() === 'error') failures.push(m.text()); });
  page.on('response', r => { if (r.status() >= 400) missing.push(`${r.status()} ${r.url()}`); });
  await page.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);
  console.log('font-ready', await page.evaluate(() => document.fonts.check('16px "Chakra Petch"') && document.fonts.check('16px Oxanium')));
  console.log('menu', await page.locator('#menu').evaluate(e => !e.classList.contains('is-hidden')));
  await page.locator('#sound-btn').click();
  console.log('sound-toggle-pressed', await page.locator('#sound-btn').getAttribute('aria-pressed'));
  await page.locator('#play-btn').click(); await page.waitForTimeout(1100);
  console.log('started', await page.locator('#hud').evaluate(e => !e.classList.contains('is-hidden')), 'wave', await page.locator('#wave-num').innerText());
  await page.keyboard.press('KeyP');
  console.log('paused', await page.locator('#pause').evaluate(e => !e.classList.contains('is-hidden')));
  await page.locator('#resume-btn').click();
  console.log('resumed', await page.locator('#pause').evaluate(e => e.classList.contains('is-hidden')));
  await page.keyboard.press('KeyP'); await page.locator('#quit-btn').click();
  console.log('returned-menu', await page.locator('#menu').evaluate(e => !e.classList.contains('is-hidden')));
  await page.locator('#play-btn').click(); await page.waitForTimeout(1000);
  await page.locator('#game-canvas').screenshot({ path: '/tmp/opencode/neon-breach-latest.jpg', type: 'jpeg', quality: 72 });
  await page.keyboard.press('KeyR'); await page.keyboard.press('Space');
  await page.keyboard.down('KeyW'); await page.waitForTimeout(250); await page.keyboard.up('KeyW');
  await page.mouse.down(); await page.waitForTimeout(250); await page.mouse.up();
  console.log('desktop-final', await page.locator('#hud').evaluate(e => !e.classList.contains('is-hidden')));
  // Allow the unarmed player to be defeated naturally to exercise the game-over lifecycle.
  await page.waitForFunction(() => !document.querySelector('#gameover').classList.contains('is-hidden'), { timeout: 85000 });
  console.log('gameover', await page.locator('#final-score').innerText(), 'accuracy', await page.locator('#final-accuracy').innerText());
  await page.locator('#restart-btn').click(); await page.waitForTimeout(350);
  console.log('restart-from-gameover', await page.locator('#hud').evaluate(e => !e.classList.contains('is-hidden')));
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  mobile.on('pageerror', e => failures.push('mobile: ' + e.message));
  mobile.on('response', r => { if (r.status() >= 400) missing.push(`mobile ${r.status()} ${r.url()}`); });
  await mobile.goto('http://localhost:3000/', { waitUntil: 'networkidle' });
  await mobile.locator('#play-btn').tap(); await mobile.waitForTimeout(300);
  console.log('touch-controls-visible', await mobile.locator('#touch-controls').evaluate(e => !e.classList.contains('is-hidden')));
  const zone = await mobile.locator('#stick-zone').boundingBox();
  await mobile.locator('#stick-zone').dispatchEvent('pointerdown', { pointerId: 7, pointerType: 'touch', clientX: zone.x + zone.width / 2, clientY: zone.y + zone.height / 2 });
  await mobile.locator('#stick-zone').dispatchEvent('pointermove', { pointerId: 7, pointerType: 'touch', clientX: zone.x + zone.width / 2 + 35, clientY: zone.y + zone.height / 2 - 20 });
  const stickMoved = await mobile.locator('#stick-thumb').evaluate(e => e.style.transform.includes('35px'));
  await mobile.locator('#stick-zone').dispatchEvent('pointerup', { pointerId: 7, pointerType: 'touch' });
  const look = await mobile.locator('#touch-look').boundingBox();
  await mobile.locator('#touch-look').dispatchEvent('pointerdown', { pointerId: 8, pointerType: 'touch', clientX: look.x + 150, clientY: look.y + 150 });
  await mobile.locator('#touch-look').dispatchEvent('pointermove', { pointerId: 8, pointerType: 'touch', clientX: look.x + 175, clientY: look.y + 165 });
  await mobile.locator('#touch-look').dispatchEvent('pointerup', { pointerId: 8, pointerType: 'touch' });
  await mobile.locator('#touch-fire').tap(); await mobile.locator('#touch-reload').tap(); await mobile.locator('#touch-jump').tap(); await mobile.locator('#touch-ads').tap();
  await mobile.locator('#touch-pause').tap();
  console.log('touch-stick-moved', stickMoved, 'touch-paused', await mobile.locator('#pause').evaluate(e => !e.classList.contains('is-hidden')));
  await mobile.locator('#resume-btn').tap();
  console.log('touch-resumed', await mobile.locator('#pause').evaluate(e => e.classList.contains('is-hidden')));
  console.log('missing-resources', missing, 'runtime-errors', failures);
  await mobile.close(); await page.close();
} finally { await browser.close(); }

