import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--no-sandbox', '--use-gl=angle', '--use-angle=swiftshader', '--enable-webgl'] });
const errors = [];
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3000/', { waitUntil: 'load' });
  await page.locator('#play-btn').click();
  await page.evaluate(() => { Math.random = () => 0; hp = 1; shield = 0; });
  await page.waitForFunction(() => !document.querySelector('#gameover').classList.contains('is-hidden'), null, { timeout: 20000 });
  console.log('actual-combat-gameover', await page.locator('#final-wave').innerText(), await page.locator('#final-accuracy').innerText());
  await page.locator('#restart-btn').click({ force: true });
  console.log('restart', await page.locator('#hud').evaluate(e => !e.classList.contains('is-hidden')));
  await page.close();

  const mobile = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true });
  mobile.on('pageerror', e => errors.push(e.message));
  await mobile.goto('http://localhost:3000/', { waitUntil: 'load' });
  await mobile.locator('#play-btn').tap();
  const zone = await mobile.locator('#stick-zone').boundingBox();
  await mobile.mouse.move(zone.x + zone.width / 2, zone.y + zone.height / 2);
  await mobile.mouse.down();
  await mobile.mouse.move(zone.x + zone.width / 2 + 35, zone.y + zone.height / 2 - 20);
  const stickMoved = await mobile.locator('#stick-thumb').evaluate(e => e.style.transform.includes('35px'));
  await mobile.mouse.up();
  const look = await mobile.locator('#touch-look').boundingBox();
  await mobile.mouse.move(look.x + 150, look.y + 100);
  await mobile.mouse.down();
  await mobile.mouse.move(look.x + 175, look.y + 115);
  await mobile.mouse.up();
  await mobile.locator('#touch-fire').tap();
  await mobile.locator('#touch-reload').tap();
  await mobile.locator('#touch-jump').tap();
  await mobile.locator('#touch-ads').tap();
  await mobile.locator('#touch-pause').tap();
  console.log('touch-stick', stickMoved, 'pause', await mobile.locator('#pause').evaluate(e => !e.classList.contains('is-hidden')));
  await mobile.locator('#resume-btn').tap();
  console.log('touch-resume', await mobile.locator('#pause').evaluate(e => e.classList.contains('is-hidden')));
  console.log('runtime-errors', errors);
  await mobile.close();
} finally { await browser.close(); }

